declare
  S jsonb := $fsiereg${"schema":"edgedesk_research_registration_v1","model_key":"fsie_nfl_team_volume","name":"NFL situational team play volume","version":"situational_v1","status":"EXPERIMENTAL","provenance":"T3","sport":"NFL","registered_at":"2026-10-29","hypothesis":"Team play volume and its pass/run split, and the player opportunities allocated from it, are predicted better out of sample by situation-normalised tendencies (down, distance, field position, clock, score), opponent adjustment, pace and a script mixture driven by the pregame expected margin than by season or recent averages.","objective":"Project team offensive plays, official pass attempts and official rush attempts with calibrated P10-P90 intervals, out of sample.","primary_metric":"MAE on the untouched holdout season (team: plays, official pass attempts, official rush attempts; player: pass attempts, rush attempts, targets, receptions)","unit":"team-game","baseline":"existing_edgedesk, market_only, recent_weighted, season_avg","training_window":"seasons 2016, 2017, 2018","validation_window":"walk-forward folds 2019, 2020, 2021, 2022, 2023, 2024","holdout_window":"season 2025 (untouched until the freeze)","machine":{"window_dates":{"training":["2016-08-01","2019-02-15"],"validation":["2019-08-01","2025-02-15"],"holdout":["2025-08-01","2026-02-15"]},"window_note":"[from, to): calendar dates spanning the seasons","minimum_sample":450,"version":"situational_v1","status":"EXPERIMENTAL","provenance":"T3"},"minimum_sample":{"team_games":450},"promotion_criteria":{"decision_rule":"every criterion below on the holdout; passing permits only a separate preregistered integration study","criteria":[{"id":"beats_season_avg","rule":"primary MAE below season_avg on plays, pass_att and rush_att, each with the bootstrap 95% CI upper bound < 0"},{"id":"beats_recent_weighted","rule":"the same against recent_weighted"},{"id":"vs_market_only","rule":"pass_att and rush_att: CI upper bound < 0 against market_only; plays: no more than 1% worse"},{"id":"interval_coverage","rule":"P10-P90 coverage in [0.74, 0.86] for each target"},{"id":"bias","rule":"|bias| <= 0.75 for each target"},{"id":"sample","rule":"at least 450 holdout team-games"}],"family_correction":"none: all criteria must hold jointly"},"forking_paths":{"alternatives_considered_not_tried":["play-level win probability for script states (point-in-time validity not established for the college feed)","gradient-boosted trees (no dependency may be added)"],"candidates_tried_on_validation":["simulation residual structure: independent possessions x plays-per-drive (P10-P90 coverage 0.97, rejected) -> game plays total + team split + possessions conditional on plays (0.81)","a point-in-time league-level feature (removed a -0.5 play trend bias)","player share shrinkage: toward a 2% prior (QB bias -5.1, rejected) -> toward last season's share / the player's own share","projected starter's pass share: history over all appearances (bias -1.7, rejected) -> share in games started, shrunk to a starter share by expected margin","NFL evaluation with pregame availability (roster status + injury report) applied, as production does","a starting-QB early-exit tail in the player simulation (pass-attempt coverage 0.74 -> 0.77 NFL, 0.71 -> 0.81 CFB)","a conditional-on-active share uplift (lower bias, higher MAE in both sports; rejected on the primary metric)","primary variant: pace_script chosen over formation, which did not improve validation MAE in either sport (NFL plays significantly worse)"],"choice_and_reason":"pace_script as primary for both sports: best pooled validation MAE on all three team targets; formation is reported as a secondary ablation."},"spec":{"targets":["plays","pass_att","rush_att"],"primary_variant":"pace_script","feature_families":{"formation":"+ observed formation/charting as a deviation from the league (0 where unobserved): shotgun and no-huddle (NFL pbp all seasons; CFB play-text tokens only from 2025), FTN motion / play action / RPO / screen / box count / blitzers (NFL 2022+)","opponent":"+ the opponent defence's faced rates, plays and plays-per-drive allowed, the opponent offence's volume, opponent-adjustment terms","pace_script":"+ pregame expected margin and total (market), |margin|, home, rest, both teams' pace, and the script MIXTURE (P(script | expected margin) x matchup rate per script)","situational":"team-only situation-normalised rates (neutral, early-down, passing-down pass rates; script-state rates mixed with league script shares), plays/drives per game, plays per drive, neutral and overall seconds per play, the league's point-in-time level"},"baselines":{"existing_edgedesk":"the props pipeline's team volume (football/props/model.js) has no historical replay, so it is compared on the live 2026 games it built, not on the holdout","market_only":"ridge on the pregame spread, total, |spread|, home and a no-line flag only - the market-informed baseline, reported separately from the season-only baselines","recent_weighted":"exponentially weighted mean, half-life 3 games, seeded with last season's mean as one game","season_avg":"the team's (player's) mean over this season's earlier games; last season's mean before its first game"},"missing_data_policy":"A play with an impossible down/distance/yard line/clock/score counts toward volume and is excluded from situational cells. A game failing a game-level gate is rejected with its reasons. A team whose attribution fails the player gate gets no player projections. Unobserved formation enters as 0 deviation, never imputed. A game with no market line uses a points-based expectation and a no-line flag (live: the EdgeDesk model's own number, labelled). College availability is unverified and widens player intervals; NFL availability uses the weekly roster and injury report as known before kickoff.","disclosure_rules":"Holdout results are published whatever they show, beside the walk-forward evidence. The holdout is evaluated once (run.js holdout refuses a second look, and refuses if this file or the model code changed after the freeze). Failing any criterion keeps the model EXPERIMENTAL and its outputs labelled research. Passing makes it eligible for a SEPARATE preregistered integration study only; it is never promoted by this registration, and VALIDATED is never written by a file. Market comparisons are projection disagreements, never betting edges.","data_already_seen":"All seasons 2014-2026 (CFB) and 2015-2026 (NFL) were ingested and passed through the quality gates before this registration, so game counts and acceptance rates of the holdout season were seen. No model was trained on, predicted or scored against a holdout-season label before the freeze: walkForward() refuses any fold at or after the holdout season. The 2026 season (live) and the props pipeline's 2026 captured prices were used to build and smoke-test the live path (projections and the market study) with a provisional fit on train+validation seasons; no 2026 result informed a model choice.","ridge_lambda":5,"frozen_choices":{"chosen_on":"walk-forward validation folds 2019,2020,2021,2022,2023,2024","phi":1,"player_kappa_multiplier":{"pass_att":8,"receptions":8,"rush_att":0.25,"targets":8}},"preregistration":"football/situational/research/preregistration.json","preregistration_sha256":"c5744045a643a390745526ce9024eb2a4b3513bea49849008fd42fc0f936beae","code_sha256":"5c3164f06ac554d3c22c138137c8556dd493298584bfa4e01d5384d6780be884"},"result":null,"content_sha256":"b3018fc5995362014c3aa09ddd6b07243f146fd8f3b0444a56bc09d060b32d69"}$fsiereg$::jsonb;
  m regclass := 'public.research_models';
