  end if;

  if vcol is not null then
    execute format('select exists (select 1 from %s where %I::text = $1 and %I::text = $2)', v, fkcol, vcol) into have using ref, S ->> 'version';
  else
    execute format('select exists (select 1 from %s where %I::text = $1)', v, fkcol) into have using ref;
  end if;
  if not have then
    vv := jsonb_build_object(fkcol, ref);
    if vcol is not null then vv := vv || jsonb_build_object(vcol, S ->> 'version'); end if;
    c := pg_temp.edr_has(v, array['status', 'model_status', 'maturity']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_label(v, c, array['experimental'])); end if;
    c := pg_temp.edr_has(v, array['provenance', 'evidence_provenance', 'tier']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_label(v, c, array['t3', 'research_model', 'research', 'model'])); end if;
    for i in 1 .. 3 loop
      c := pg_temp.edr_has(v, pairs[i:i][1:4]::text[]);
      if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> (wkeys[i] || '_window'),
        jsonb_build_object('from', mach -> 'window_dates' -> wkeys[i] -> 0, 'to', mach -> 'window_dates' -> wkeys[i] -> 1, 'description', S ->> (wkeys[i] || '_window')),
        mach -> 'window_dates' -> wkeys[i])); end if;
    end loop;
    c := pg_temp.edr_has(v, array['objective', 'goal']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'objective', null, null)); end if;
    c := pg_temp.edr_has(v, array['hypothesis']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'hypothesis', null, null)); end if;
    c := pg_temp.edr_has(v, array['min_sample', 'minimum_sample', 'min_n', 'sample_target']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, (mach -> 'minimum_sample')::text,
      case when pg_temp.edr_typ(v, c) in ('jsonb', 'json') then S -> 'minimum_sample' else mach -> 'minimum_sample' end, null)); end if;
    c := pg_temp.edr_has(v, array['success_metric', 'primary_metric', 'metric']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'primary_metric', null, null)); end if;
    c := pg_temp.edr_has(v, array['promotion_criteria', 'decision_rule', 'criteria', 'success_criteria']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S -> 'promotion_criteria' ->> 'decision_rule', S -> 'promotion_criteria', null)); end if;
    c := pg_temp.edr_has(v, array['forking_paths', 'forking_paths_disclosure', 'disclosure', 'garden_of_forking_paths']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, null, S -> 'forking_paths', null)); end if;
    c := pg_temp.edr_has(v, array['spec', 'metadata', 'meta', 'params', 'config', 'details', 'definition', 'protocol']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, null, S -> 'spec' || jsonb_build_object('content_sha256', S ->> 'content_sha256'), null)); end if;
    c := pg_temp.edr_has(v, array['notes', 'description']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c,
      'Preregistered ' || (S ->> 'registered_at') || ' from football/situational/research/preregistration.json (sha256 ' || (S -> 'spec' ->> 'preregistration_sha256') || ').', null, null)); end if;
    perform pg_temp.edr_insert(v, vv, fkcol);
  end if;
end $reg$;

do $reg$
declare
  S jsonb := $fsiereg${"schema":"edgedesk_research_registration_v1","model_key":"fsie_cfb_player_volume","name":"CFB situational player opportunity (all FBS)","version":"situational_v1","status":"EXPERIMENTAL","provenance":"T3","sport":"NCAAF","registered_at":"2026-10-29","hypothesis":"Team play volume and its pass/run split, and the player opportunities allocated from it, are predicted better out of sample by situation-normalised tendencies (down, distance, field position, clock, score), opponent adjustment, pace and a script mixture driven by the pregame expected margin than by season or recent averages.","objective":"Project player pass attempts, rush attempts, targets and receptions with calibrated P10-P90 intervals, out of sample.","primary_metric":"MAE on the untouched holdout season (team: plays, official pass attempts, official rush attempts; player: pass attempts, rush attempts, targets, receptions)","unit":"player-game","baseline":"existing_edgedesk, market_only, recent_weighted, season_avg","training_window":"seasons 2015, 2016","validation_window":"walk-forward folds 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024","holdout_window":"season 2025 (untouched until the freeze)","machine":{"window_dates":{"training":["2015-08-01","2017-02-15"],"validation":["2017-08-01","2025-02-15"],"holdout":["2025-08-01","2026-02-15"]},"window_note":"[from, to): calendar dates spanning the seasons","minimum_sample":2000,"version":"situational_v1","status":"EXPERIMENTAL","provenance":"T3"},"minimum_sample":{"qb_starts":700,"other_rows":2000},"promotion_criteria":{"decision_rule":"every criterion below on the holdout; passing permits only a separate preregistered integration study","criteria":[{"id":"beats_player_season_avg","rule":"model MAE below the player's season average for every market, CI upper bound < 0"},{"id":"beats_player_recent_weighted","rule":"the same against the player's recent weighted average"},{"id":"player_interval_coverage","rule":"P10-P90 coverage in [0.70, 0.90] for every market (discrete counts)"},{"id":"player_bias","rule":"|bias| <= 1.0 for pass attempts and <= 0.5 for the other markets"},{"id":"player_sample","rule":"at least 700 evaluated quarterback starts and 2000 rows per other market"}],"family_correction":"none: all criteria must hold jointly"},"forking_paths":{"alternatives_considered_not_tried":["play-level win probability for script states (point-in-time validity not established for the college feed)","gradient-boosted trees (no dependency may be added)"],"candidates_tried_on_validation":["simulation residual structure: independent possessions x plays-per-drive (P10-P90 coverage 0.97, rejected) -> game plays total + team split + possessions conditional on plays (0.81)","a point-in-time league-level feature (removed a -0.5 play trend bias)","player share shrinkage: toward a 2% prior (QB bias -5.1, rejected) -> toward last season's share / the player's own share","projected starter's pass share: history over all appearances (bias -1.7, rejected) -> share in games started, shrunk to a starter share by expected margin","NFL evaluation with pregame availability (roster status + injury report) applied, as production does","a starting-QB early-exit tail in the player simulation (pass-attempt coverage 0.74 -> 0.77 NFL, 0.71 -> 0.81 CFB)","a conditional-on-active share uplift (lower bias, higher MAE in both sports; rejected on the primary metric)","primary variant: pace_script chosen over formation, which did not improve validation MAE in either sport (NFL plays significantly worse)"],"choice_and_reason":"pace_script as primary for both sports: best pooled validation MAE on all three team targets; formation is reported as a secondary ablation."},"spec":{"targets":["pass_att","rush_att","targets","receptions"],"primary_variant":"pace_script","feature_families":{"formation":"+ observed formation/charting as a deviation from the league (0 where unobserved): shotgun and no-huddle (NFL pbp all seasons; CFB play-text tokens only from 2025), FTN motion / play action / RPO / screen / box count / blitzers (NFL 2022+)","opponent":"+ the opponent defence's faced rates, plays and plays-per-drive allowed, the opponent offence's volume, opponent-adjustment terms","pace_script":"+ pregame expected margin and total (market), |margin|, home, rest, both teams' pace, and the script MIXTURE (P(script | expected margin) x matchup rate per script)","situational":"team-only situation-normalised rates (neutral, early-down, passing-down pass rates; script-state rates mixed with league script shares), plays/drives per game, plays per drive, neutral and overall seconds per play, the league's point-in-time level"},"baselines":{"existing_edgedesk":"the props pipeline's team volume (football/props/model.js) has no historical replay, so it is compared on the live 2026 games it built, not on the holdout","market_only":"ridge on the pregame spread, total, |spread|, home and a no-line flag only - the market-informed baseline, reported separately from the season-only baselines","recent_weighted":"exponentially weighted mean, half-life 3 games, seeded with last season's mean as one game","season_avg":"the team's (player's) mean over this season's earlier games; last season's mean before its first game"},"missing_data_policy":"A play with an impossible down/distance/yard line/clock/score counts toward volume and is excluded from situational cells. A game failing a game-level gate is rejected with its reasons. A team whose attribution fails the player gate gets no player projections. Unobserved formation enters as 0 deviation, never imputed. A game with no market line uses a points-based expectation and a no-line flag (live: the EdgeDesk model's own number, labelled). College availability is unverified and widens player intervals; NFL availability uses the weekly roster and injury report as known before kickoff.","disclosure_rules":"Holdout results are published whatever they show, beside the walk-forward evidence. The holdout is evaluated once (run.js holdout refuses a second look, and refuses if this file or the model code changed after the freeze). Failing any criterion keeps the model EXPERIMENTAL and its outputs labelled research. Passing makes it eligible for a SEPARATE preregistered integration study only; it is never promoted by this registration, and VALIDATED is never written by a file. Market comparisons are projection disagreements, never betting edges.","data_already_seen":"All seasons 2014-2026 (CFB) and 2015-2026 (NFL) were ingested and passed through the quality gates before this registration, so game counts and acceptance rates of the holdout season were seen. No model was trained on, predicted or scored against a holdout-season label before the freeze: walkForward() refuses any fold at or after the holdout season. The 2026 season (live) and the props pipeline's 2026 captured prices were used to build and smoke-test the live path (projections and the market study) with a provisional fit on train+validation seasons; no 2026 result informed a model choice.","ridge_lambda":5,"frozen_choices":{"chosen_on":"walk-forward validation folds 2017,2018,2019,2020,2021,2022,2023,2024","phi":0.9,"player_kappa_multiplier":{"pass_att":2,"receptions":8,"rush_att":1,"targets":8}},"preregistration":"football/situational/research/preregistration.json","preregistration_sha256":"c5744045a643a390745526ce9024eb2a4b3513bea49849008fd42fc0f936beae","code_sha256":"5c3164f06ac554d3c22c138137c8556dd493298584bfa4e01d5384d6780be884"},"result":null,"content_sha256":"94f3fa97635fbd3f2ea6a3aeb39764dbdf4788e15bd79ab2e03545c3a4f59a5c"}$fsiereg$::jsonb;
  m regclass := 'public.research_models';
  v regclass := 'public.research_model_versions';
  mv jsonb; vv jsonb; mach jsonb := S -> 'machine';
  kcol text; ncol text; refcol text; fkcol text; vcol text; c text; ref text; have boolean;
  pairs text[][] := array[
    array['training_window', 'train_window', 'training_period', 'training'],
    array['validation_window', 'valid_window', 'validation_period', 'validation'],
    array['holdout_window', 'holdout_period', 'holdout', 'test_window']];
  wkeys text[] := array['training', 'validation', 'holdout'];
  i int;
begin
  kcol := pg_temp.edr_has(m, array['model_key', 'key', 'model_name', 'model', 'slug', 'code', 'name']);
  if kcol is null then raise exception 'research registry: research_models has no key column — nothing was registered'; end if;
  select a.attname::text, ra.attname::text into fkcol, refcol
    from pg_constraint k
    join pg_attribute a on a.attrelid = k.conrelid and a.attnum = k.conkey[1]
    join pg_attribute ra on ra.attrelid = k.confrelid and ra.attnum = k.confkey[1]
   where k.contype = 'f' and k.conrelid = v and k.confrelid = m limit 1;
  if fkcol is null then
    fkcol := pg_temp.edr_has(v, array['model_key', 'model_id', 'research_model_id', 'model']);
    refcol := case when fkcol in ('model_id', 'research_model_id') then pg_temp.edr_has(m, array['id', 'model_id']) else kcol end;
  end if;
  if fkcol is null or refcol is null then raise exception 'research registry: cannot tell how research_model_versions points at research_models — nothing was registered'; end if;
  vcol := pg_temp.edr_has(v, array['version', 'model_version', 'version_label', 'semver', 'label']);

  execute format('select %I::text from %s where %I::text = $1 limit 1', refcol, m, kcol) into ref using S ->> 'model_key';
  if ref is null then
    mv := jsonb_build_object(kcol, S ->> 'model_key');
    ncol := pg_temp.edr_has(m, array['name', 'title', 'display_name', 'label']);
    if ncol is not null and ncol <> kcol then mv := mv || jsonb_build_object(ncol, S ->> 'name'); end if;
    c := pg_temp.edr_has(m, array['sport', 'league']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'sport'); end if;
    c := pg_temp.edr_has(m, array['status', 'model_status', 'maturity']); if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_label(m, c, array['experimental'])); end if;
    c := pg_temp.edr_has(m, array['provenance', 'evidence_provenance', 'tier', 'evidence_tier']);
    if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_label(m, c, array['t3', 'research_model', 'research', 'model'])); end if;
    c := pg_temp.edr_has(m, array['objective', 'goal']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'objective'); end if;
    c := pg_temp.edr_has(m, array['hypothesis']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'hypothesis'); end if;
    c := pg_temp.edr_has(m, array['description', 'summary']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'hypothesis'); end if;
    c := pg_temp.edr_has(m, array['family', 'category', 'module', 'domain']); if c is not null then mv := mv || jsonb_build_object(c, 'football_situational'); end if;
    c := pg_temp.edr_has(m, array['owner', 'created_by', 'registered_by']); if c is not null then mv := mv || jsonb_build_object(c, (S ->> 'registered_at') || ' preregistration (EdgeDesk research)'); end if;
    c := pg_temp.edr_has(m, array['metadata', 'meta', 'spec', 'details', 'config']);
    if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_val(m, c, null, S, null)); end if;
    ref := pg_temp.edr_insert(m, mv, refcol);
    raise notice 'research registry: % registered', S ->> 'model_key';
  else
    raise notice 'research registry: % was already registered and is left as it is', S ->> 'model_key';
  end if;

  if vcol is not null then
    execute format('select exists (select 1 from %s where %I::text = $1 and %I::text = $2)', v, fkcol, vcol) into have using ref, S ->> 'version';
  else
    execute format('select exists (select 1 from %s where %I::text = $1)', v, fkcol) into have using ref;
  end if;
  if not have then
    vv := jsonb_build_object(fkcol, ref);
    if vcol is not null then vv := vv || jsonb_build_object(vcol, S ->> 'version'); end if;
    c := pg_temp.edr_has(v, array['status', 'model_status', 'maturity']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_label(v, c, array['experimental'])); end if;
    c := pg_temp.edr_has(v, array['provenance', 'evidence_provenance', 'tier']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_label(v, c, array['t3', 'research_model', 'research', 'model'])); end if;
    for i in 1 .. 3 loop
      c := pg_temp.edr_has(v, pairs[i:i][1:4]::text[]);
      if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> (wkeys[i] || '_window'),
        jsonb_build_object('from', mach -> 'window_dates' -> wkeys[i] -> 0, 'to', mach -> 'window_dates' -> wkeys[i] -> 1, 'description', S ->> (wkeys[i] || '_window')),
        mach -> 'window_dates' -> wkeys[i])); end if;
    end loop;
    c := pg_temp.edr_has(v, array['objective', 'goal']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'objective', null, null)); end if;
    c := pg_temp.edr_has(v, array['hypothesis']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'hypothesis', null, null)); end if;
    c := pg_temp.edr_has(v, array['min_sample', 'minimum_sample', 'min_n', 'sample_target']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, (mach -> 'minimum_sample')::text,
      case when pg_temp.edr_typ(v, c) in ('jsonb', 'json') then S -> 'minimum_sample' else mach -> 'minimum_sample' end, null)); end if;
    c := pg_temp.edr_has(v, array['success_metric', 'primary_metric', 'metric']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'primary_metric', null, null)); end if;
    c := pg_temp.edr_has(v, array['promotion_criteria', 'decision_rule', 'criteria', 'success_criteria']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S -> 'promotion_criteria' ->> 'decision_rule', S -> 'promotion_criteria', null)); end if;
    c := pg_temp.edr_has(v, array['forking_paths', 'forking_paths_disclosure', 'disclosure', 'garden_of_forking_paths']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, null, S -> 'forking_paths', null)); end if;
    c := pg_temp.edr_has(v, array['spec', 'metadata', 'meta', 'params', 'config', 'details', 'definition', 'protocol']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, null, S -> 'spec' || jsonb_build_object('content_sha256', S ->> 'content_sha256'), null)); end if;
    c := pg_temp.edr_has(v, array['notes', 'description']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c,
      'Preregistered ' || (S ->> 'registered_at') || ' from football/situational/research/preregistration.json (sha256 ' || (S -> 'spec' ->> 'preregistration_sha256') || ').', null, null)); end if;
    perform pg_temp.edr_insert(v, vv, fkcol);
  end if;
end $reg$;

